#!/usr/bin/env python3
"""
Parser for TSL specification - improved version
"""
import re
from collections import defaultdict

def parse_tsl(filename):
    """Parse TSL file and return structured data."""
    with open(filename, 'r') as f:
        lines = f.readlines()

    categories = []
    current_category = None
    current_subcategory = None

    for line in lines:
        stripped = line.strip()

        # Skip empty lines and comments
        if not stripped or stripped.startswith('#'):
            continue

        # Count leading spaces for indentation level
        indent = len(line) - len(line.lstrip())

        # Main category (no indentation, ends with :)
        if indent == 0 and stripped.endswith(':'):
            current_category = stripped.rstrip(':')
            categories.append({
                'name': current_category,
                'choices': []
            })
            current_subcategory = None
            continue

        # Subcategory (some indentation, ends with :)
        if indent > 0 and stripped.endswith(':') and current_category:
            current_subcategory = stripped.rstrip(':')
            # Add to current category
            if 'subcategories' not in categories[-1]:
                categories[-1]['subcategories'] = []
                categories[-1]['choices'] = []
            categories[-1]['subcategories'].append(current_subcategory)
            continue

        # Choice line (more indentation, no colon at end)
        if indent > 0 and current_category and not stripped.endswith(':'):
            # This is a choice within a subcategory
            # Format: "value [annotations]..."
            choice = {
                'value': stripped,
                'annotations': []
            }

            # Extract annotations
            anns = re.findall(r'\[([^\]]+)\]', stripped)
            choice['annotations'] = [a.strip() for a in anns]

            # The value is the part before any brackets
            match = re.match(r'^([^[]*)', stripped)
            if match:
                choice['value'] = match.group(1).strip()
            else:
                choice['value'] = stripped

            if 'choices' not in categories[-1]:
                categories[-1]['choices'] = []
            categories[-1]['choices'].append(choice)
            current_subcategory = None  # Reset since we're at choice level

    return categories

def print_structure(categories, indent=0):
    """Print the parsed structure."""
    for cat in categories:
        print(" " * indent + f"Category: {cat['name']}")
        if 'subcategories' in cat:
            for subcat in cat['subcategories']:
                print(" " * (indent + 2) + f"  Subcategory: {subcat}")
                if 'choices' in cat:
                    for choice in cat['choices']:
                        print(" " * (indent + 4) + f"    - {choice['value']}: {choice['annotations']}")
        elif 'choices' in cat:
            for choice in cat['choices']:
                print(" " * (indent + 2) + f"  - {choice['value']}: {choice['annotations']}")

def main():
    categories = parse_tsl('/workdir/data/input_tsl.txt')
    print_structure(categories)

if __name__ == '__main__':
    main()
