                current_cat = None  # This shouldn't happen but safety
            if current_subcat not in result[-1]['subcategories']:
                result[-1]['subcategories'][current_subcat] = []
            continue

        # Choice
        if indent > 0 and current_cat is not None and not stripped.endswith(':'):
            choice = {
                'value': stripped,
                'annotations': re.findall(r'\[([^\]]+)\]', stripped)
            }
            # Extract value before brackets
            match = re.match(r'^([^[]*)', stripped)
            if match:
                choice['value'] = match.group(1).strip()

            # Add to current subcategory's choices
            if current_subcat in result[-1]['subcategories']:
                result[-1]['subcategories'][current_subcat].append(choice)
            else:
                # Fallback: add to main category if somehow we lost track
                result[-1]['subcategories'][current_subcat] = [choice]

    return result

